DISCLOSURE_TEXT = (
    "This report is generated by an automated analysis "
    "system for informational purposes only and does not "
    "constitute registered investment advice under SEBI "
    "regulations. Consult a qualified financial advisor "
    "before making investment decisions."
)


def governance_agent(state):

    print(
        "\n[Governance Agent] "
        "Applying compliance and review rules..."
    )

    verification = state.get(
        "verification_result",
        {}
    )

    investment_verdicts = state.get(
        "investment_analysis",
        {}
    ).get(
        "verdicts",
        {}
    )

    risk_assessments = state.get(
        "risk_assessment",
        {}
    ).get(
        "assessments",
        {}
    )

    comparison_by_ticker = {
        entry["ticker"]: entry
        for entry in state.get(
            "comparison_analysis",
            {}
        ).get(
            "ranking",
            []
        )
    }

    per_ticker_flags = {
        ticker: list(flags)
        for ticker, flags in verification.get(
            "per_ticker_flags",
            {}
        ).items()
    }

    review_flags = []

    # Rule: a Severe/High risk read alongside a Buy/Hold
    # recommendation needs an analyst's eyes before it
    # reaches the user, regardless of how confident either
    # agent was individually.
    for ticker, assessment in risk_assessments.items():

        verdict = (
            investment_verdicts.get(ticker)
            or comparison_by_ticker.get(ticker)
        )

        if verdict is None:
            continue

        if (
            assessment.get("risk_level") == "Severe"
            and verdict.get("recommendation") in ("Buy", "Hold")
        ):

            per_ticker_flags.setdefault(
                ticker,
                []
            ).append("HIGH_RISK_RECOMMENDATION")

            review_flags.append("HIGH_RISK_RECOMMENDATION")

    # Rule: an LLM fallback compounded with low confidence
    # is worse than either alone - the deterministic
    # fallback text was never actually reconciled against
    # the qualitative signals.
    for ticker, flags in verification.get(
        "per_ticker_flags",
        {}
    ).items():

        flag_set = set(flags)

        if (
            "LLM_SYNTHESIS_FALLBACK" in flag_set
            and "LOW_CONFIDENCE" in flag_set
        ):

            per_ticker_flags.setdefault(
                ticker,
                []
            ).append("UNRELIABLE_SYNTHESIS")

            review_flags.append("UNRELIABLE_SYNTHESIS")

        if "UNRECONCILED_RISK_SIGNAL" in flag_set:

            per_ticker_flags.setdefault(
                ticker,
                []
            ).append("REQUIRES_ANALYST_RECONCILIATION")

            review_flags.append("REQUIRES_ANALYST_RECONCILIATION")

    requires_human_review = bool(review_flags)

    governance_result = {

        "status":
            "review_required" if requires_human_review else "cleared",

        "flags":
            sorted(set(review_flags)),

        "per_ticker_flags":
            per_ticker_flags,

        "disclosure":
            DISCLOSURE_TEXT,

    }

    return {

        "governance_result":
            governance_result,

        "requires_human_review":
            requires_human_review,

        "current_agent":
            "governance_agent",

        "next_action":
            "generate_report",

        "audit_log": [
            {
                "agent":
                    "governance_agent",

                "action":
                    "governance_checks_completed",

                "status":
                    governance_result["status"],

                "flags":
                    governance_result["flags"],
            }
        ],

    }
